import React, { useEffect, useState } from "react";
import AOS from "aos";
import "aos/dist/aos.css";
import GLightbox from "glightbox";
import "glightbox/dist/css/glightbox.css";
import Isotope from "isotope-layout";
import "bootstrap/dist/css/bootstrap.min.css";
import Pooja from "../assets/poojasharma.png";

const Portfolio = () => {
    const [filters, setFilters] = useState([]);

    useEffect(() => {
        // Initialize AOS for animations
        AOS.init({
            duration: 600,
            easing: "ease-in-out",
            once: true,
            mirror: false,
        });

        // Initialize GLightbox for lightbox functionality
        const glightbox = GLightbox({
            selector: ".glightbox",
        });

        // Initialize Isotope for filtering
        const iso = new Isotope(".isotope-container", {
            itemSelector: ".isotope-item",
            layoutMode: "masonry",
        });

        // Filter button functionality
        const filterButtons = document.querySelectorAll(".portfolio-filters li");
        filterButtons.forEach((button) =>
            button.addEventListener("click", function () {
                filterButtons.forEach((btn) =>
                    btn.classList.remove("filter-active")
                );
                this.classList.add("filter-active");

                const filterValue = this.getAttribute("data-filter");
                iso.arrange({ filter: filterValue });
            })
        );

        // Cleanup on unmount
        return () => {
            iso.destroy();
            glightbox.destroy();
        };
    }, []);

    // Extract unique filters from the projects array
    useEffect(() => {
        const allFilters = new Set();
        projects.forEach((project) => {
            const filters = project.filter.split(", ");
            filters.forEach((filter) => allFilters.add(filter.trim().toLowerCase()));  // Normalize casing and trim spaces
        });
        setFilters(["All", ...Array.from(allFilters).map((filter) => filter.charAt(0).toUpperCase() + filter.slice(1))]);  // Capitalize the first letter
    }, []);
    

    return (
        <main className="main">
            <section id="portfolio" className="portfolio section">
                <div className="container">
                    <div
                        className="isotope-layout"
                        data-default-filter="*"
                        data-layout="masonry"
                        data-sort="original-order"
                    >
                        <div className="row align-items-center py-5">
                            <div className="col-lg-7 portfolio-info ">
                                <h3>Hey, I am Yasir Masood</h3>
                                <p>
                                    Here are some of my work, Contact me for more details...
                                </p>
                            </div>
                            <div className="col-lg-5 text-center text-lg-end">
                                <ul
                                    className="portfolio-filters isotope-filters"
                                    data-aos="fade-up"
                                    data-aos-delay="100"
                                >
                                    {filters.map((filter, index) => (
                                        <li
                                            key={index}
                                            data-filter={filter === "All" ? "*" : `.${filter}`}
                                            className={filter === "All" ? "filter-active" : ""}
                                        >
                                            {filter}
                                        </li>
                                    ))}
                                </ul>
                            </div>
                        </div>

                        <div
                            className="row gy-4 mb-4 isotope-container"
                            data-aos="fade-up"
                            data-aos-delay="200"
                        >
                            {projects.map((item, index) => (
                                <div
                                    key={index}
                                    className={`col-lg-4 col-md-6 portfolio-item isotope-item ${item.filter
                                        .split(", ")
                                        .map((filter) => filter.trim())
                                        .join(" ")}`}
                                >
                                    
                                    <div className="portfolio-content h-100 border rounded-3">

                                        <img
                                            src={item.image}
                                            className="img-fluid w-100"
                                            alt={item.heading}
                                            style={{ height: "230px"}}
                                        />
                                        <div className="portfolio-info" style={{backgroundColor: "rgba(248, 82, 59, 0.8)"}}>
                                            <h4>{item.heading}</h4>
                                            <p>{item.description}</p>
                                            <div>
                                                <a
                                                    href={item.link}
                                                    title={item.heading}
                                                    className=" preview-link btn bg-custom btn-lg"
                                                    target="_blank"
                                                >
                                                    View Demo
                                                </a>
                                               
                                            </div>
                                        </div>
                                    </div>
                                </div>
                            ))}

                        </div>
                    </div>
                </div>
            </section>
        </main>
    );
};

