import React, { useState } from 'react';
import 'bootstrap/dist/css/bootstrap.min.css';
import 'bootstrap/dist/js/bootstrap.bundle.min';

const Navbar = ({ navigateTo }) => {
  const [isOpen, setIsOpen] = useState(false);

  const handleToggle = () => {
    setIsOpen(!isOpen);
  };

  return (
    <nav className="navbar navbar-expand-lg navbar-dark bg-custom">
      <div className="container-fluid px-5">

        <button
          className="navbar-toggler"
          type="button"
          onClick={handleToggle}
          aria-controls="navbarNavAltMarkup"
          aria-expanded={isOpen}
          aria-label="Toggle navigation"
        >
          <span className="navbar-toggler-icon"></span>
        </button>

        <div className={`collapse navbar-collapse ${isOpen ? 'show' : ''}`} id="navbarNavAltMarkup">
          <div className="navbar-nav">
            <a href="#home" onClick={(e) => { e.preventDefault(); navigateTo("/home"); }} className="nav-link text-white"><b>Home</b></a>
            <a href="#aboutus" onClick={(e) => { e.preventDefault(); navigateTo("/aboutus"); }} className="nav-link text-white"><b>About</b></a>
            <a href="#skills" onClick={(e) => { e.preventDefault(); navigateTo("/skillss"); }} className="nav-link text-white"><b>Skills</b></a>
            <a href="#experience" onClick={(e) => { e.preventDefault(); navigateTo("/experience"); }} className="nav-link text-white"><b>Experience</b></a>
            <a href="#portfolio" onClick={(e) => { e.preventDefault(); navigateTo("/portfolio"); }} className="nav-link text-white"><b>Portfolio</b></a>
            <a href="#contact" onClick={(e) => { e.preventDefault(); navigateTo("/contact"); }} className="nav-link text-white"><b>Contact</b></a>
          </div>
        </div>
        <a className="navbar-brand text-white" href="#home"><b>Yasir Masood</b></a>
      </div>
    </nav>
  );
};

export default Navbar;
